// ✏️ عدّل هذه القائمة حسب اختيارك
const WATCHLIST = [
  // أمن سيبراني
  'PANW', 'CRWD', 'FTNT', 'ZS', 'OKTA',
  // برامج هندسية
  'ANSS', 'SNPS', 'CDNS',
  // خدمات تقنية
  'EPAM', 'GLOB',
  // رعاية صحية
  'IDXX', 'HOLX', 'PODD',
  // طاقة متجددة
  'NEE', 'BEP',
  // صناعية
  'ROK', 'NOVT'
];

return WATCHLIST.map(ticker => ({ json: { ticker } }));

const ticker = $('قائمة المراقبة').item.json.ticker;
const data = $json;

if (data.error || data.message) {
  return { json: { ticker, halal: false, status: 'ERROR', purification_rate: null, sector: '', reason: 'API Error' } };
}

const status = data.shariaComplianceStatus ?? 'UNKNOWN';
const purification = parseFloat(data.purificationPercentage ?? 0);
const isHalal = status === 'COMPLIANT' && purification === 0;

return {
  json: {
    ticker,
    halal: isHalal,
    purification_rate: purification,
    status,
    sector: data.businessSector ?? '',
    reason: isHalal ? '' : (
      status !== 'COMPLIANT'
        ? `الحالة: ${status}`
        : `تطهير ${purification}%`
    )
  }
};

const all = $input.all().map(i => i.json);
const today = new Date().toLocaleDateString('ar-SA', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const halal = all.filter(r => r.halal);
const rejected = all.filter(r => !r.halal);

const lines = [
  `📅 ${today}`,
  ``,
  `✅ الأسهم الحلال (تطهير 0%) — ${halal.length} سهم:`,
  ...halal.map(r => `  • ${r.ticker}  (${r.sector || 'غير محدد'})`),
  ``,
  `❌ المرفوضة — ${rejected.length} سهم:`,
  ...rejected.map(r => `  • ${r.ticker}: ${r.reason}`)
];

return [{
  json: {
    message: lines.join('\n'),
    halal_tickers: halal.map(r => r.ticker),
    rejected_tickers: rejected.map(r => r.ticker),
    total: all.length,
    halal_count: halal.length,
    date: today
  }
}];
